<?php
declare(strict_types=1);
define('WP_CLI',true);require __DIR__.'/bootstrap.php';
use AISkillsHub\Core\Learning\SubscriptionCampaigns;
if(!defined('AISH_ACCOUNT_MAIL_KEY_VERSION')||AISH_ACCOUNT_MAIL_KEY_VERSION!=='p14qa')exit(4);
$subscriptions=$core->get('learning_subscriptions');$worker=$core->get('account_mail_worker');$store=$core->get('account_store');$saved=$subscriptions->snapshot();wp_set_current_user($admin);$subscriptions->saveConfig(['enabled'=>true,'paused'=>false],$saved['revision']);
$newUsers=[];$skills=[];$issue=0;$captured=[];
add_filter('pre_wp_mail',static function($value,$message)use(&$captured){$captured[]=$message;return true;},PHP_INT_MAX,2);
$subscribe=function(string $name,string $locale='en_US')use($subscriptions,$store,$db,&$newUsers):int{$id=p14_user($name);$newUsers[]=$id;wp_set_current_user($id);$subscriptions->request(['locale'=>$locale,'weekly'=>true,'new_resources'=>true,'consent'=>true],bin2hex(random_bytes(32)));$row=$db->row('SELECT * FROM '.$db->table('notification_outbox')." WHERE recipient_user_id=%d AND template_key='newsletter_confirm' ORDER BY id DESC LIMIT 1",[$id]);p14_assert($subscriptions->confirm($store->decryptPayload($row)['token'])==='active','QA subscriber explicitly confirms own request');return$id;};
$recipientMail=function(int $user,int $issueId)use($db):?array{$rows=$db->rows('SELECT * FROM '.$db->table('notification_outbox')." WHERE recipient_user_id=%d AND template_key='newsletter_weekly' ORDER BY id DESC",[$user]);foreach($rows as$r){if(hash_equals($r['event_key'],hash('sha256','newsletter-issue:'.$issueId.':'.$user.':'.$GLOBALS['subscriptions']->rawState($user)['generation'].':'.$GLOBALS['subscriptions']->rawState($user)['email_hash'])))return$r;}return null;};
// Test-only query constraint keeps a worker on one synthetic row instead of draining retained mail.
$send=function(int $id)use($db,$worker):void{$table=$db->table('notification_outbox');$db->execute("UPDATE $table SET available_at='1971-01-01 00:00:00' WHERE id=%d",[$id]);$limit=static function(string$sql)use($table,$id):string{if(str_starts_with($sql,"SELECT * FROM $table WHERE status IN ('queued','retry')")&&str_ends_with($sql,' LIMIT 1 FOR UPDATE'))return str_replace(' ORDER BY ',' AND id='.(int)$id.' ORDER BY ',$sql);return$sql;};add_filter('query',$limit,PHP_INT_MAX);try{$worker->run();}finally{remove_filter('query',$limit,PHP_INT_MAX);}};
$read=fn(int$id):?array=>$db->row('SELECT * FROM '.$db->table('notification_outbox').' WHERE id=%d',[$id]);
try{
 $owner=$subscribe('campaign-owner');$cancel=$subscribe('campaign-cancel');$paused=$subscribe('campaign-paused');$raceA=$subscribe('campaign-race-a');$raceB=$subscribe('campaign-race-b');$zh=$subscribe('campaign-chinese','zh_CN');
 for($i=0;$i<6;$i++)$skills[]=p14_skill('campaign-public-'.$i);$draft=p14_skill('campaign-private',false);wp_set_current_user($admin);
 p14_case('issue_exact_preview_public_language_and_private_native_storage',function()use($subscriptions,$skills,$draft,$db,&$issue){
  $preview=$subscriptions->preview('en_US');p14_assert(count($preview['items'])>0&&count($preview['items'])<=12,'Preview is bounded actual published content');p14_assert(!in_array($draft,array_column($preview['items'],'id'),true),'Draft Skill excluded from curated snapshot');foreach($preview['items']as$item)p14_assert(str_contains($item['url'],'/en/'),'All approved references in selected language');
  p14_reject(fn()=>$subscriptions->queueIssue('en_US','weekly',bin2hex(random_bytes(32)),str_repeat('0',64)),'Wrong preview fingerprint cannot queue');$issue=$subscriptions->queueIssue('en_US','weekly',bin2hex(random_bytes(32)),$preview['fingerprint']);p14_assert($issue>0&&get_post($issue)->post_status==='private'&&get_post($issue)->post_type===SubscriptionCampaigns::TYPE,'Issue is private native snapshot, not second mail queue');
  p14_assert($subscriptions->queueIssue('en_US','weekly',bin2hex(random_bytes(32)),$preview['fingerprint'])===$issue,'Same locale/week replay deduplicates');$state=json_decode(get_post($issue)->post_content,true);p14_assert(isset($state['refs'],$state['approved'])&&!str_contains(get_post($issue)->post_content,'@example.invalid'),'Issue snapshot contains IDs/fingerprints, not subscriber addresses');
 });
 p14_case('batch_fault_rolls_back_recipient_cursor_then_retry_resumes_without_duplicates',function()use($subscriptions,$db,&$issue){
  $table=$db->table('notification_outbox');$inserts=0;$fail=static function(string$sql)use($table,&$inserts):string{if(str_starts_with($sql,'INSERT INTO '.$table.' ')&&str_contains($sql,'newsletter_weekly')&&++$inserts===2)return'INSERT INTO aish_phase14_missing_campaign_table (id) VALUES (1)';return$sql;};
  add_filter('query',$fail,PHP_INT_MAX);try{for($i=0;$i<30;$i++){ $subscriptions->tick();$s=$subscriptions->issueDetail($issue);if(in_array($s['state'],['failed','complete'],true))break; }}finally{remove_filter('query',$fail,PHP_INT_MAX);}
  p14_assert($inserts===2&&$subscriptions->issueDetail($issue)['state']==='failed','Actual second recipient INSERT failure records resumable issue failure');$before=$subscriptions->issueDetail($issue);$subscriptions->retryIssue($issue);p14_assert($subscriptions->issueDetail($issue)['cursor']===$before['cursor'],'Retry preserves last committed cursor');
  for($i=0;$i<30;$i++){ $subscriptions->tick();if($subscriptions->issueDetail($issue)['state']==='complete')break; }p14_assert($subscriptions->issueDetail($issue)['state']==='complete','Bounded recipient chunks resume to completion');
  p14_assert(!(int)$db->value("SELECT COUNT(*) FROM (SELECT event_key,COUNT(*) n FROM $table WHERE template_key='newsletter_weekly' GROUP BY event_key HAVING n>1) a"),'Existing outbox event key guarantees no duplicate delivery rows');p14_reject(fn()=>$subscriptions->retryIssue($issue),'Completed issue cannot be replayed as failed work');
 });
 p14_case('same_generation_digest_headers_and_live_public_gate',function()use($subscriptions,$owner,$issue,$recipientMail,$send,$read,&$captured,$skills,$management,$db){
  $mail=$recipientMail($owner,$issue);p14_assert($mail!==null,'Real batch queued confirmed recipient');$target=end($skills);$name=$db->value('SELECT title FROM '.$db->table('skill_translations').' WHERE skill_id=%d AND locale=%s',[$target,'en_US']);$management->archiveSkill($target,p14_skill_revision($target));$before=count($captured);$send((int)$mail['id']);$sent=$read((int)$mail['id']);p14_assert($sent['status']==='accepted'&&count($captured)===$before+1,'Existing worker accepts one intercepted digest');$message=end($captured);p14_assert(!str_contains($message['message'],$name),'Resource archived after issue approval is rechecked and removed before transport');$headers=is_array($message['headers'])?implode("\n",$message['headers']):(string)$message['headers'];p14_assert(str_contains($headers,'List-Unsubscribe:')&&str_contains($headers,'List-Unsubscribe-Post: List-Unsubscribe=One-Click'),'Standard one-click cancellation headers are present');p14_assert(str_contains($message['message'],'Unsubscribe:')&&!str_contains($message['message'],'Private QA'),'Rendered body includes cancel link without private notes');
 });
 p14_case('unsubscribe_before_worker_prevents_transport_and_security_mail_is_unaffected',function()use($subscriptions,$cancel,$issue,$recipientMail,$send,$read,&$captured,$core,$db){$mail=$recipientMail($cancel,$issue);wp_set_current_user($cancel);$subscriptions->accountUnsubscribe();$before=count($captured);$send((int)$mail['id']);p14_assert($read((int)$mail['id'])['status']==='cancelled'&&count($captured)===$before,'Cancellation wins before dispatch and makes no mail attempt');$security=$core->get('account_mail')->queueSecurity($cancel,get_userdata($cancel)->user_email,'en_US','password_changed');$send($security);p14_assert($read($security)['status']==='accepted','Required security message still uses existing outbox after newsletter withdrawal');});
 p14_case('global_pause_defers_same_row_and_resume_preserves_attempt_budget',function()use($subscriptions,$paused,$issue,$recipientMail,$send,$read,&$captured,$admin){wp_set_current_user($admin);$mail=$recipientMail($paused,$issue);$subscriptions->saveConfig(['enabled'=>true,'paused'=>true],$subscriptions->snapshot()['revision']);$before=count($captured);$send((int)$mail['id']);$deferred=$read((int)$mail['id']);p14_assert(in_array($deferred['status'],['queued','retry'],true)&&$deferred['payload_ciphertext']!==null&&count($captured)===$before,'Pause keeps known-unsent encrypted row recoverable');p14_assert((int)$deferred['attempts']===0,'Pause does not consume transport retry budget');$subscriptions->saveConfig(['enabled'=>true,'paused'=>false],$subscriptions->snapshot()['revision']);$send((int)$mail['id']);p14_assert($read((int)$mail['id'])['status']==='accepted','Resume dispatches original row once');});
 p14_case('chinese_issue_reuses_curated_content_and_only_selected_language',function()use($subscriptions,$zh,$db,$store,$send,$read,&$captured,$admin){wp_set_current_user($admin);$preview=$subscriptions->preview('zh_CN');$id=$subscriptions->queueIssue('zh_CN','weekly',bin2hex(random_bytes(32)),$preview['fingerprint']);for($i=0;$i<30;$i++){$subscriptions->tick();if($subscriptions->issueDetail($id)['state']==='complete')break;}p14_assert($subscriptions->issueDetail($id)['state']==='complete','Chinese batch finishes its bounded cursor');$rows=$db->rows('SELECT * FROM '.$db->table('notification_outbox')." WHERE recipient_user_id=%d AND template_key='newsletter_weekly' ORDER BY id DESC",[$zh]);$mail=$rows[0]??null;p14_assert($mail!==null&&$mail['locale']==='zh_CN','Chinese subscriber gets corresponding issue');$send((int)$mail['id']);p14_assert($read((int)$mail['id'])['status']==='accepted','Chinese digest reaches only intercepted transport');$message=end($captured);p14_assert(str_contains($message['subject'],'每周精选')&&str_contains($message['message'],'/zh/'),'Bilingual template and URLs match');});
 wp_set_current_user($admin);$a=$recipientMail($raceA,$issue);$b=$recipientMail($raceB,$issue);update_option('aish_p14_newsletter_race',['a'=>$raceA,'b'=>$raceB,'mail_a'=>(int)$a['id'],'mail_b'=>(int)$b['id'],'saved'=>$saved],false);
}finally{wp_set_current_user($admin);$subscriptions->saveConfig(array_intersect_key($saved,['enabled'=>true,'paused'=>true]),$subscriptions->snapshot()['revision']);}
p14_report('Real WordPress/MySQL approved campaign snapshots, bounded cursor fault recovery, live public gates and one existing outbox; worker selection is test-constrained to owned rows; all transport responses are Mock, never real SMTP/delivery');
